        ' -f content="$(printf %s ' + shellQuote(json) + ' | base64)"';
}

function historyPutCommand(state, cfg, index, existingSha) {
    var repo = (cfg && cfg.repo) || state.repo;
    var base = assetName(state, cfg).replace(/\.json$/, '');
