    var hasChanges = false;
    if (status.trim()) {
        const commitMsg = configLoader.formatTemplate(config.formats.commitMessage.rework, {ticketKey: ticketKey});
        cmd('git commit -m "' + commitMsg + '"');
        console.log('✅ Committed rework changes');
        hasChanges = true;

