    var put = 'gh api -X PUT repos/' + repo + '/contents/' + path +
        ' -f branch=' + tagOf(cfg) +
        ' -f message=' + shellQuote('factory state history — ' +
            ((state.tick && state.tick.at) || '') + ' [skip ci]') +
        ' -f content="$(printf %s ' + shellQuote(JSON.stringify(index)) +
        ' | base64)"';
    if (existingSha) {
